# ── API ──────────────────────────────────────────────

def t(key: str, lang: str = "zh", **params) -> str:
    """获取翻译文本，支持参数替换.

    Args:
        key: I18N_MAP 中的 key
        lang: "zh" 或 "en"
        **params: 替换 {param_name} 占位符

    Returns:
        翻译后的文本；若 key 不存在则返回 "⚠key"
    """
    entry = I18N_MAP.get(key, {})
    text = entry.get(lang) or entry.get("zh") or f"⚠{key}"
    if params:
        text = text.format(**params)
    return text


def t_legacy(zh_text: str, lang: str = "zh") -> str:
    """兼容旧 orchestrator._l() 的调用方式：用中文文本查找翻译.

    优先查 _LEGACY_MSG_MAP → 新 I18N_MAP，找不到做部分匹配，最后回退到原中文。
    """
    if lang == "zh":
        return zh_text

    new_key = _LEGACY_MSG_MAP.get(zh_text)
    if new_key:
        return t(new_key, lang)

    # fallback: partial match
    for legacy_zh, mapped_key in _LEGACY_MSG_MAP.items():
        if legacy_zh in zh_text:
            translated_part = t(mapped_key, lang)
            return zh_text.replace(legacy_zh, translated_part)

    return zh_text


def validate_i18n_coverage() -> list[str]:
    """返回所有缺少 en 翻译的 key."""
    return [k for k, v in I18N_MAP.items() if "en" not in v]


